import csv


def answer() -> int:
    # Four parent links from Dawid Majtyka lead to Przemysław Kurczab.
    # His children have these numbers of grandchildren in the diagram:
    grandchildren = {
        ("Liwia", "Maligłówka"): 3,
        ("Julianna", "Paściak"): 0,
        ("Julita", "Kucharz"): 1,
        ("Alan", "Wocial"): 3,
    }
    with open("/app/dataset/people_accounts.csv", newline="", encoding="utf-8") as f:
        return sum(
            int(person["account_balance"])
            for person in csv.DictReader(f)
            if grandchildren.get((person["first_name"], person["last_name"]), 0) > 1
        )


if __name__ == "__main__":
    import json

    with open("/app/answer.json", "w") as f:
        json.dump(answer(), f, default=list)
